from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import subprocess
repo=Path('/workspace/scratch/f433637a99a0/quds_office_suite')
checks=repo/'docs/validation/mail-keyboard-triage-20261121/checks'
manifest=json.loads((checks/'incoming-word-source-manifest.json').read_text())
changed=[path for path,digest in manifest['source_sha256'].items() if hashlib.sha256((repo/path).read_bytes()).hexdigest()!=digest]
assert not changed, {'source_changed':changed}
counts=json.loads((checks/'incoming-word-test-counts-final.json').read_text())
assert counts['substantive_tests']==205 and counts['runner_success'] and not counts['failures'] and not counts['skipped'], counts
names=['incoming-word-tests-final','incoming-word-strcomp-vm-final','incoming-word-colors-vm-final','incoming-word-strcomp-js-compile-final','incoming-word-strcomp-js-final','incoming-word-colors-js-compile-final','incoming-word-colors-js-final']
receipts={}
for name in names:
    receipt=json.loads((checks/(name+'.json')).read_text())
    assert receipt['status']=='PASS' and receipt['exit_code']==0, receipt
    log=checks/receipt['log']
    assert hashlib.sha256(log.read_bytes()).hexdigest()==receipt['log_sha256'], name
    receipts[name]={'receipt':name+'.json','log':receipt['log'],'elapsed_seconds':receipt['elapsed_seconds'],'log_sha256':receipt['log_sha256']}
smokes={}
for kind in ['strcomp','colors']:
    vm=(checks/('incoming-word-'+kind+'-vm-final.log')).read_bytes()
    js=(checks/('incoming-word-'+kind+'-js-final.log')).read_bytes()
    assert vm==js, kind+' VM/JS outputs differ'
    result=json.loads(vm)
    if kind=='strcomp':
        assert result['cases']==72 and len(result['receipts'])==72, result
        detail={'portable_receipts':result['cases'],'host_languages':sorted(set(x['host'] for x in result['receipts']))}
    else:
        assert result['operations']==9 and result['recordedSteps']==9 and result['additionalReopens']==2 and result['lateRollback'] and result['policyRefusals']==3 and len(result['nativePartSha256'])==3, result
        detail=result
    smokes[kind]={'vm_js_output_bytes_equal':True,'output_sha256':hashlib.sha256(vm).hexdigest(),'details':detail,'counted_as_unit_tests':False}
summary={'status':'PASS','finished_utc':datetime.now(timezone.utc).isoformat(),'source_manifest':'incoming-word-source-manifest.json','tested_source_unchanged':True,'source_files':len(manifest['source_sha256']),'workspace_head_at_start':manifest['workspace_head'],'workspace_head_at_completion':subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip(),'unit_tests':{'substantive_passed':counts['substantive_tests'],'failed':0,'skipped':0,'per_file':counts['per_file'],'excluded_loader_setup_teardown':len(counts['excluded_hidden_or_loader_setup_events'])},'smokes':smokes,'receipts':receipts,'github_actions':'NOT USED','scope':'Fresh targeted incoming Word checks after formatting; no installed Microsoft Office host comparison.'}
(checks/'incoming-word-validation-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps(summary))
